suppressPackageStartupMessages({library(ComplexHeatmap);library(circlize);library(grid);library(jsonlite)})
root<-normalizePath(commandArgs(TRUE)[1]);source(file.path(Sys.getenv('BIOFIGURE_ROOT'),'scripts/figure_style.R'));bf_complexheatmap_font(bf_font('Arial'));options(warn=2);d<-read.csv(file.path(root,'input.csv'));genes<-unique(d$protein);samples<-unique(d$sample);stopifnot(length(genes)==16,length(samples)==38,!anyDuplicated(paste(d$protein,d$sample)))
m<-matrix(d$z,nrow=16,ncol=38,byrow=TRUE,dimnames=list(genes,samples));stopifnot(all(m[cbind(match(d$protein,genes),match(d$sample,samples))]==d$z))
z<-t(scale(t(m)));stopifnot(max(abs(rowMeans(z)))<1e-12,max(abs(apply(z,1,sd)-1))<1e-12);write.csv(z,file.path(root,'plot_matrix.csv'))
md<-d[match(samples,d$sample),c('sample','group','age')];write.csv(md,file.path(root,'sample_metadata.csv'),row.names=FALSE)
gp<-function(...)gpar(fontfamily='Arial',fontsize=7,...);ha<-HeatmapAnnotation(Group=factor(md$group,c('Control','Treatment')),`Age (years)`=md$age,simple_anno_size=unit(2,'mm'),gap=unit(1,'mm'),col=list(Group=c(Control='#4DBBD5',Treatment='#E64B35'),`Age (years)`=colorRamp2(c(25,50,75),c('#E4EEEF','#9BCDCE','#009B5C'))),annotation_name_gp=gp(),annotation_name_side='left',show_legend=TRUE,annotation_legend_param=list(Group=list(title_gp=gp(),labels_gp=gp()),`Age (years)`=list(title_gp=gp(),labels_gp=gp(),at=c(25,50,75))))
# 38 columns include a2mm split gap: body width=95+2mm, height=40mm.
ht<-Heatmap(z,name='Row z score',col=colorRamp2(seq(-2,2,length.out=101),viridisLite::cividis(101)),width=unit(97,'mm'),height=unit(40,'mm'),column_split=factor(md$group,c('Control','Treatment')),column_gap=unit(2,'mm'),cluster_column_slices=FALSE,column_title=NULL,show_column_names=FALSE,row_names_gp=gp(),row_names_max_width=unit(23,'mm'),row_dend_width=unit(9,'mm'),column_dend_height=unit(8,'mm'),rect_gp=gpar(col='white',lwd=.18),border=TRUE,top_annotation=ha,heatmap_legend_param=list(title_gp=gp(),labels_gp=gp(),at=c(-2,0,2),legend_height=unit(18,'mm')))
metrics<-list();render<-function(){drawn<-draw(ht,heatmap_legend_side='right',annotation_legend_side='right',merge_legends=TRUE,padding=unit(c(5,4,5,4),'mm'));for(s in 1:2){decorate_heatmap_body('Row z score',{w<-convertWidth(unit(1,'npc'),'mm',valueOnly=TRUE);h<-convertHeight(unit(1,'npc'),'mm',valueOnly=TRUE);cw<-w/19;ch<-h/16;stopifnot(abs(cw/ch-1)<.01);metrics[[s]]<<-list(slice=s,rows=16,columns=19,body_width_mm=w,body_height_mm=h,cell_width_mm=cw,cell_height_mm=ch)},column_slice=s)};write_json(list(row_order=rownames(z)[row_order(drawn)],column_order=lapply(column_order(drawn),function(v)colnames(z)[v])),file.path(root,'order.json'),auto_unbox=TRUE,pretty=TRUE)}
ragg::agg_png(file.path(root,'figure.png'),width=165,height=85,units='mm',res=400,background='white');render();dev.off()
quartz(type='pdf',file=file.path(root,'figure.pdf'),width=165/25.4,height=85/25.4,family='Arial');render();dev.off()
svglite::svglite(file.path(root,'figure.svg'),width=165/25.4,height=85/25.4);render();dev.off()
write_json(list(canvas_mm=c(165,85),slices=metrics,annotation_height_mm=2,input_preserved=TRUE,transformation='rowz using sample SD; old input column z actually held raw simulated values',color_clipping=c(-2,2),excluded=0,font='Arial'),file.path(root,'geometry.json'),pretty=TRUE,auto_unbox=TRUE,digits=15);writeLines(capture.output(sessionInfo()),file.path(root,'environment.txt'));cat('SQUARE_HEATMAP_OK\n')
